                else if (tag == 5 || tag == 6) { d.skipBytes(8); i++; }
                else if (tag == 7 || tag == 8 || tag == 16 || tag == 19 || tag == 20) d.skipBytes(2);
                else if (tag == 15) d.skipBytes(3);
                else d.skipBytes(4);
            }
